import React, { useState } from 'react';
import { Link, useNavigate } from 'react-router-dom';

const Navbar = () => {
  const [showPerbandingan, setShowPerbandingan] = useState(false);
  const navigate = useNavigate();

  const closeDropdowns = () => {
    setShowPerbandingan(false);
  };

  const handleLogout = () => {
    localStorage.removeItem('isAdminLoggedIn');
    localStorage.removeItem('adminUsername');
    navigate('/login-admin');
  };

  return (
    <nav
      className="navbar navbar-expand-lg navbar-light bg-light"
      style={{ padding: '10px 30px', borderBottom: '1px solid #ddd' }}
    >
      <Link className="navbar-brand fw-bold" to="/criterias" onClick={closeDropdowns}>
        AHP System
      </Link>

      <div className="d-flex" style={{ gap: '20px', alignItems: 'center' }}>
        <Link to="/criterias" onClick={closeDropdowns}>Kriteria</Link>
        <Link to="/alternatives" onClick={closeDropdowns}>Alternatif</Link>

        {/* Dropdown Perbandingan */}
        <div className="position-relative">
          <button
            className="btn btn-link p-0"
            style={{ textDecoration: 'none' }}
            onClick={() => setShowPerbandingan((prev) => !prev)}
          >
            Perbandingan ▾
          </button>
          {showPerbandingan && (
            <div
              className="position-absolute bg-white shadow-sm"
              style={{ top: '100%', left: 0, padding: '8px', minWidth: '180px', zIndex: 10 }}
            >
              <Link className="d-block py-1" to="/critratios" onClick={closeDropdowns}>
                Perbandingan Kriteria
              </Link>
              <Link className="d-block py-1" to="/altratios" onClick={closeDropdowns}>
                Perbandingan Alternatif
              </Link>
            </div>
          )}
        </div>

        <Link to="/hitung" onClick={closeDropdowns}>Hasil</Link>
        <Link to="/user" onClick={closeDropdowns}>User</Link>

        <button
          className="btn btn-sm btn-outline-danger"
          onClick={handleLogout}
        >
          Logout
        </button>
      </div>
    </nav>
  );
};

export default Navbar;
